-- Run with psql from the repository root after data/schema.sql
BEGIN;
SET CONSTRAINTS ALL DEFERRED;
\copy roles (role_code, display_name) FROM 'data/seed/generated/roles.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy villages (village_id, source_code, name, district, city_province, is_active) FROM 'data/seed/generated/villages.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy user_accounts (user_id, email, password_hash, role_code, admin_type, account_status, full_name, title, phone, must_change_password, created_at, updated_at) FROM 'data/seed/generated/user_accounts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy account_status_history (history_id, user_id, from_status, to_status, changed_by, changed_at, reason) FROM 'data/seed/generated/account_status_history.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy ubnd_village_assignments (ubnd_user_id, village_id, assigned_by, assigned_at) FROM 'data/seed/generated/ubnd_village_assignments.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy agency_registration_requests (registration_request_id, email, pending_password_hash, current_status, agency_user_id, current_version_no, created_at, updated_at) FROM 'data/seed/generated/agency_registration_requests.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy registration_otp_challenges (challenge_id, registration_request_id, email, otp_verifier, issued_at, expires_at, used_at, invalidated_at, attempt_count, resend_sequence) FROM 'data/seed/generated/registration_otp_challenges.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy registration_resubmission_tokens (token_id, registration_request_id, token_verifier, issued_at, expires_at, used_at, invalidated_at) FROM 'data/seed/generated/registration_resubmission_tokens.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy registration_submission_versions (registration_request_id, version_no, submitted_at, submitted_by, full_name, company_name, company_type, tax_id, location, contact_information, team_size, tour_types) FROM 'data/seed/generated/registration_submission_versions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy stored_files (file_id, storage_key, file_name, media_type, file_size_bytes, uploaded_by, created_at) FROM 'data/seed/generated/stored_files.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy registration_documents (registration_request_id, version_no, file_id, document_type) FROM 'data/seed/generated/registration_documents.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy agency_review_records (review_id, registration_request_id, registration_version_no, major_change_id, hdt_user_id, decision, comments, decided_at) FROM 'data/seed/generated/agency_review_records.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy agency_profiles (agency_id, user_id, registration_request_id, company_name, company_type, tax_id, location, description, contact_info, team_size, tour_types, created_at, updated_at) FROM 'data/seed/generated/agency_profiles.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy provider_profiles (provider_id, user_id, village_id, business_registration_number, current_version_no, published_version_no, verification_status, created_at, updated_at) FROM 'data/seed/generated/provider_profiles.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy provider_profile_versions (provider_id, version_no, version_status, business_name, craft_type, artisan_names, location_address, description, contact_information, booking_conditions, submitted_at, published_at) FROM 'data/seed/generated/provider_profile_versions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy provider_verification_reviews (review_id, provider_id, version_no, reviewer_user_id, decision, revision_comments, reviewed_at) FROM 'data/seed/generated/provider_verification_reviews.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy provider_operating_hours (operating_hour_id, provider_id, weekday, local_start, local_end) FROM 'data/seed/generated/provider_operating_hours.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy experiences (experience_id, provider_id, name, description, category, duration_minutes, price_per_person, max_participants, notice_period_hours, experience_location_address, cancellation_policy, archived_at, created_at, updated_at) FROM 'data/seed/generated/experiences.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy profile_media (profile_media_id, file_id, agency_id, provider_id, experience_id, category, display_order) FROM 'data/seed/generated/profile_media.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy provider_version_media (provider_id, version_no, file_id, category, display_order) FROM 'data/seed/generated/provider_version_media.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy quote_requests (quote_request_id, agency_id, experience_id, source, created_at) FROM 'data/seed/generated/quote_requests.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy bookings (booking_id, agency_id, provider_id, experience_id, source_chat_session_id, start_at, duration_minutes, group_size, agreed_price_total, conditions_snapshot, status, created_at, updated_at, hold_expires_at, arrival_at) FROM 'data/seed/generated/bookings.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy booking_status_history (history_id, booking_id, from_status, to_status, changed_by, changed_at, reason) FROM 'data/seed/generated/booking_status_history.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy chat_sessions (chat_session_id, agency_id, provider_id, source, experience_id, quote_request_id, booking_id, status, started_at, last_message_at, closed_at, closed_by) FROM 'data/seed/generated/chat_sessions.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy chat_messages (message_id, chat_session_id, sender_user_id, text, message_kind, booking_id, sent_at) FROM 'data/seed/generated/chat_messages.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy chat_participants (chat_session_id, user_id, last_read_message_id, unread_count) FROM 'data/seed/generated/chat_participants.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
\copy notifications (notification_id, recipient_user_id, event_type, source_type, source_id, payload, created_at, read_at, email_delivery_status) FROM 'data/seed/generated/notifications.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8', NULL '');
COMMIT;
